// postgresqlQueries answers every query in Querier against postgresql.
type postgresqlQueries struct {
	archiveList                     string
	archiveSignup                   string
	createList                      string
	getList                         string
	getListCreatedAt                string
	getSignup                       string
	getSignupByContactDigest        string
	getSignupCreatedAt              string
	insertSignup                    string
	listLists                       string
	listListsDescending             string
	listOpenLists                   string
	listOpenListsDescending         string
	listSignups                     string
	listSignupsDescending           string
	listSignupsForSubject           string
	listSignupsForSubjectDescending string
	transitionSignup                string
	updateList                      string
	updateSignupNotes               string
	withdrawSignup                  string
	withdrawSignupsForSubject       string
}

// newPostgreSQL returns the postgresql querier with prefix substituted into every
// table name the analyzer identified.
func newPostgreSQL(prefix string) *postgresqlQueries {
	return &postgresqlQueries{
		archiveList:                     strings.ReplaceAll(archiveListPostgreSQL, prefixMarker, prefix),
		archiveSignup:                   strings.ReplaceAll(archiveSignupPostgreSQL, prefixMarker, prefix),
		createList:                      strings.ReplaceAll(createListPostgreSQL, prefixMarker, prefix),
		getList:                         strings.ReplaceAll(getListPostgreSQL, prefixMarker, prefix),
		getListCreatedAt:                strings.ReplaceAll(getListCreatedAtPostgreSQL, prefixMarker, prefix),
		getSignup:                       strings.ReplaceAll(getSignupPostgreSQL, prefixMarker, prefix),
		getSignupByContactDigest:        strings.ReplaceAll(getSignupByContactDigestPostgreSQL, prefixMarker, prefix),
		getSignupCreatedAt:              strings.ReplaceAll(getSignupCreatedAtPostgreSQL, prefixMarker, prefix),
		insertSignup:                    strings.ReplaceAll(insertSignupPostgreSQL, prefixMarker, prefix),
		listLists:                       strings.ReplaceAll(listListsPostgreSQL, prefixMarker, prefix),
		listListsDescending:             strings.ReplaceAll(listListsDescendingPostgreSQL, prefixMarker, prefix),
		listOpenLists:                   strings.ReplaceAll(listOpenListsPostgreSQL, prefixMarker, prefix),
		listOpenListsDescending:         strings.ReplaceAll(listOpenListsDescendingPostgreSQL, prefixMarker, prefix),
		listSignups:                     strings.ReplaceAll(listSignupsPostgreSQL, prefixMarker, prefix),
		listSignupsDescending:           strings.ReplaceAll(listSignupsDescendingPostgreSQL, prefixMarker, prefix),
		listSignupsForSubject:           strings.ReplaceAll(listSignupsForSubjectPostgreSQL, prefixMarker, prefix),
		listSignupsForSubjectDescending: strings.ReplaceAll(listSignupsForSubjectDescendingPostgreSQL, prefixMarker, prefix),
		transitionSignup:                strings.ReplaceAll(transitionSignupPostgreSQL, prefixMarker, prefix),
		updateList:                      strings.ReplaceAll(updateListPostgreSQL, prefixMarker, prefix),
		updateSignupNotes:               strings.ReplaceAll(updateSignupNotesPostgreSQL, prefixMarker, prefix),
		withdrawSignup:                  strings.ReplaceAll(withdrawSignupPostgreSQL, prefixMarker, prefix),
		withdrawSignupsForSubject:       strings.ReplaceAll(withdrawSignupsForSubjectPostgreSQL, prefixMarker, prefix),
	}
}

// ArchiveList runs the :execrows query against postgresql.
func (q *postgresqlQueries) ArchiveList(ctx context.Context, db DBTX, arg ArchiveListParams) (int64, error) {
	result, err := db.ExecContext(ctx, q.archiveList,
		arg.ID,
		arg.Scope,
	)
	if err != nil {
		return 0, err
	}

	return result.RowsAffected()
}

